// A TypeScript language service plugin that lets the editor read the region
// literals #{ ... } and #[ ... ] of region-js as plain object and array
// literals. The # before { or [ is replaced with a space, so the text keeps
// its length and every position, error and hover stays where it was.
//
// #{ or #[ is never valid JavaScript otherwise (private names start with a
// letter), so only strings, comments and regular expressions can contain it,
// and there a space instead of # does not change what TypeScript checks.
'use strict';

const REGION_LITERAL = /#(?=[{[])/g;
const SCRIPT = /\.[cm]?jsx?$/;

function hideRegionLiterals(text) {
  return text.includes('#{') || text.includes('#[')
    ? text.replace(REGION_LITERAL, ' ')
    : text;
}

function init({ typescript: ts }) {
  return {
    create(info) {
      const host = info.languageServiceHost;
      const getScriptSnapshot = host.getScriptSnapshot.bind(host);
      host.getScriptSnapshot = (fileName) => {
        const snapshot = getScriptSnapshot(fileName);
        if (!snapshot || !SCRIPT.test(fileName)) return snapshot;
        const text = snapshot.getText(0, snapshot.getLength());
        const hidden = hideRegionLiterals(text);
        return hidden === text ? snapshot : ts.ScriptSnapshot.fromString(hidden);
      };
      info.project?.projectService?.logger?.info(
        'region-literals-ts-plugin: #{ } and #[ ] read as { } and [ ]',
      );
      return info.languageService;
    },
  };
}

init.hideRegionLiterals = hideRegionLiterals;
module.exports = init;
